CREATE TABLE public.habits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK (length(trim(title)) > 0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.habits TO authenticated; GRANT ALL ON public.habits TO service_role;
ALTER TABLE public.habits ENABLE ROW LEVEL SECURITY;
CREATE POLICY habits_owner ON public.habits FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.habit_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), habit_id uuid NOT NULL REFERENCES public.habits(id) ON DELETE CASCADE, checked_on date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(habit_id, checked_on));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.habit_checks TO authenticated; GRANT ALL ON public.habit_checks TO service_role;
ALTER TABLE public.habit_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY habit_checks_owner ON public.habit_checks FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.habits h WHERE h.id = habit_id AND h.user_id = auth.uid()));
CREATE TABLE public.energy_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() UNIQUE, weight_kg numeric NOT NULL CHECK(weight_kg BETWEEN 20 AND 350), height_cm numeric NOT NULL CHECK(height_cm BETWEEN 80 AND 250), age integer NOT NULL CHECK(age BETWEEN 18 AND 100), sex text NOT NULL CHECK(sex IN ('female','male')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.energy_profiles TO authenticated; GRANT ALL ON public.energy_profiles TO service_role;
ALTER TABLE public.energy_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY energy_profiles_owner ON public.energy_profiles FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.energy_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), activity text NOT NULL, minutes numeric NOT NULL CHECK(minutes > 0 AND minutes <= 1440), calories numeric NOT NULL CHECK(calories >= 0), occurred_on date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.energy_activities TO authenticated; GRANT ALL ON public.energy_activities TO service_role;
ALTER TABLE public.energy_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY energy_activities_owner ON public.energy_activities FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.financial_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK(length(trim(title)) > 0), target_amount numeric NOT NULL CHECK(target_amount > 0), saved_amount numeric NOT NULL DEFAULT 0 CHECK(saved_amount >= 0), target_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.financial_goals TO authenticated; GRANT ALL ON public.financial_goals TO service_role;
ALTER TABLE public.financial_goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY financial_goals_owner ON public.financial_goals FOR ALL TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());